/* Lesson content. Every lesson follows the same spine — concrete anchor, then the
   representational figures, then the abstract form — so concreteness fading is
   structural rather than a per-lesson decision. */

/* Two parts, one course. Part II is a sequel and NOT a gate — a reader who came
   for the dogfighting can start at 13 and follow the cross-references back when
   a chapter tells them they need one. Nothing in the course locks, because the
   only thing holding a reader here is that they still want to be here. */
export const PARTS = [
  {
    n: 1, title: "Flight Dynamics", plate: "aircraft",
    lede: "Twelve ideas in the order they make sense. Every one names the thing you " +
      "probably believe that isn't true, then takes it apart until it is obvious. " +
      "Pick a callout, or start at one.",
  },
  {
    n: 2, title: "Air Combat", plate: "combat",
    lede: "Eight more, about what changes when there are two of you. Same physics, " +
      "read as a problem someone else is trying to solve first.",
  },
];

/* The whole course's name, built from its parts rather than typed — so adding a
   part cannot leave a title bar quietly claiming the course is still only about
   the first one. A chapter page names its own PART instead: a page about beyond
   visual range is not flight dynamics, and saying so in the tab would be the
   same small dishonesty as a mislabelled figure. */
export const COURSE = PARTS.map((p) => p.title).join(" & ");

export const partOf = (id) => LESSONS.find((l) => l.id === id)?.part ?? 1;
export const lessonsIn = (n) => LESSONS.filter((l) => l.part === n);

const F = (html, plain, terms) => ({ t: "formula", html, plain, terms });

